#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static tree *copy_tree(const tree *source) {
    if (!source)
        return NULL;
    tree *result = (tree *)malloc(sizeof(tree));
    result->value = source->value;
    result->left = copy_tree(source->left);
    result->right = copy_tree(source->right);
    return result;
}
static void free_tree(tree *root) {
    if (!root)
        return;
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}
zipper zipper_from_tree(const tree *root) {
    zipper result = {NULL, NULL, NULL, 0};
    result.root = result.focus = copy_tree(root);
    return result;
}
/* Rebuild the focus path in the copied snapshot, never copying pointers from
 * the old snapshot into the new one. This simple C implementation trades O(n)
 * copying for straightforward ownership. Path-copying trees can reduce edits
 * to O(depth) when shared nodes have reference-counted lifetimes. */
static zipper copy_zipper(const zipper *source) {
    zipper result = zipper_from_tree(source->root);
    if (!source->focus)
        return result;
    result.depth = source->depth;
    result.ancestors = (tree **)malloc(result.depth * sizeof(tree *));
    for (size_t i = 0; i < result.depth; ++i) {
        result.ancestors[i] = result.focus;
        const tree *child =
            i + 1 == source->depth ? source->focus : source->ancestors[i + 1];
        result.focus = source->ancestors[i]->left == child ? result.focus->left
                                                           : result.focus->right;
    }
    return result;
}
zipper zipper_clone(const zipper *source) { return copy_zipper(source); }
static zipper down(const zipper *source, bool left) {
    zipper empty = {NULL, NULL, NULL, 0};
    if (!source->focus || !(left ? source->focus->left : source->focus->right))
        return empty;
    zipper result = copy_zipper(source);
    result.ancestors =
        (tree **)realloc(result.ancestors, (result.depth + 1) * sizeof(tree *));
    result.ancestors[result.depth++] = result.focus;
    result.focus = left ? result.focus->left : result.focus->right;
    return result;
}
zipper zipper_left(const zipper *z) { return down(z, true); }
zipper zipper_right(const zipper *z) { return down(z, false); }
zipper zipper_up(const zipper *z) {
    zipper empty = {NULL, NULL, NULL, 0};
    if (!z->focus || !z->depth)
        return empty;
    zipper result = copy_zipper(z);
    result.focus = result.ancestors[--result.depth];
    return result;
}
int zipper_value(const zipper *z) { return z->focus->value; }
zipper zipper_set_value(const zipper *z, int value) {
    zipper result = copy_zipper(z);
    if (result.focus)
        result.focus->value = value;
    return result;
}
zipper zipper_set_left(const zipper *z, const tree *subtree) {
    zipper result = copy_zipper(z);
    if (result.focus) {
        free_tree(result.focus->left);
        result.focus->left = copy_tree(subtree);
    }
    return result;
}
zipper zipper_set_right(const zipper *z, const tree *subtree) {
    zipper result = copy_zipper(z);
    if (result.focus) {
        free_tree(result.focus->right);
        result.focus->right = copy_tree(subtree);
    }
    return result;
}
const tree *zipper_to_tree(const zipper *z) { return z->root; }
void zipper_free(zipper *z) {
    free_tree(z->root);
    free(z->ancestors);
    z->root = z->focus = NULL;
    z->ancestors = NULL;
    z->depth = 0;
}

solution.zipper.hpp:
#pragma once
#include <memory>
#include <optional>
#include <stdexcept>
#include <vector>

namespace persistent_zipper {
struct Node;
using Tree = std::shared_ptr<const Node>;
struct Node {
    int value;
    Tree left, right;
    static Tree make(int value, Tree left = {}, Tree right = {}) {
        return std::make_shared<const Node>(
            Node{value, std::move(left), std::move(right)});
    }
};
/* Immutable shared_ptr nodes make ordinary Zipper copies safe. Edits copy only
 * the focus and ancestor path; unchanged subtrees share ownership through RAII.
 * This is a C++ alternative to the exercise's explicit C-compatible ownership API. */
class Zipper {
    struct Crumb {
        int value;
        Tree sibling;
        bool from_left;
    };
    Tree focus_;
    std::vector<Crumb> ancestors_;
    Zipper(Tree focus, std::vector<Crumb> ancestors)
        : focus_(std::move(focus)), ancestors_(std::move(ancestors)) {}
    std::optional<Zipper> down(bool left) const {
        if (!focus_)
            return std::nullopt;
        const auto &child = left ? focus_->left : focus_->right;
        if (!child)
            return std::nullopt;
        auto path = ancestors_;
        path.push_back({focus_->value, left ? focus_->right : focus_->left, left});
        return Zipper(child, std::move(path));
    }

  public:
    explicit Zipper(Tree tree) : focus_(std::move(tree)) {}
    int value() const {
        if (!focus_)
            throw std::logic_error("empty zipper");
        return focus_->value;
    }
    std::optional<Zipper> left() const { return down(true); }
    std::optional<Zipper> right() const { return down(false); }
    std::optional<Zipper> up() const {
        if (ancestors_.empty())
            return std::nullopt;
        auto path = ancestors_;
        const auto crumb = path.back();
        path.pop_back();
        auto parent = Node::make(crumb.value, crumb.from_left ? focus_ : crumb.sibling,
                                 crumb.from_left ? crumb.sibling : focus_);
        return Zipper(std::move(parent), std::move(path));
    }
    Zipper set_value(int value) const {
        return Zipper(Node::make(value, focus_->left, focus_->right), ancestors_);
    }
    Zipper set_left(Tree subtree) const {
        return Zipper(Node::make(value(), std::move(subtree), focus_->right),
                      ancestors_);
    }
    Zipper set_right(Tree subtree) const {
        return Zipper(Node::make(value(), focus_->left, std::move(subtree)),
                      ancestors_);
    }
    Tree to_tree() const {
        auto current = *this;
        while (auto parent = current.up())
            current = std::move(*parent);
        return current.focus_;
    }
};
} // namespace persistent_zipper

tests.test_exercise.cpp:
#include "exercise.h"
#include "zipper.hpp"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}

int main(void) {
    tree leaf = {3, NULL, NULL}, left_tree = {2, NULL, &leaf},
         right_tree = {4, NULL, NULL};
    tree root = {1, &left_tree, &right_tree};
    zipper original = zipper_from_tree(&root);
    assert(original.focus && zipper_value(&original) == 1);
    zipper clone = zipper_clone(&original);
    assert(clone.focus && clone.root != original.root && zipper_value(&clone) == 1);
    zipper missing_up = zipper_up(&original);
    assert(!missing_up.focus);
    zipper left = zipper_left(&original);
    assert(left.focus && zipper_value(&left) == 2 && zipper_value(&original) == 1);
    zipper missing_left = zipper_left(&left);
    assert(!missing_left.focus);
    zipper deep = zipper_right(&left);
    assert(deep.focus && zipper_value(&deep) == 3);
    zipper changed = zipper_set_value(&deep, 30);
    assert(zipper_to_tree(&changed)->left->right->value == 30);
    assert(zipper_value(&deep) == 3 && zipper_value(&left) == 2);
    assert(zipper_to_tree(&original)->left->right->value == 3 &&
           root.left->right->value == 3);
    /* Independent branches retain their values after subsequent edits/navigation. */
    zipper sibling = zipper_set_value(&deep, 50);
    assert(zipper_value(&changed) == 30 && zipper_value(&sibling) == 50);
    zipper parent = zipper_up(&changed);
    assert(parent.focus && zipper_value(&parent) == 2 && zipper_value(&changed) == 30);
    zipper removed = zipper_set_right(&parent, NULL);
    assert(!zipper_to_tree(&removed)->left->right);
    assert(zipper_to_tree(&parent)->left->right->value == 30);
    zipper inserted = zipper_set_left(&removed, &right_tree);
    assert(zipper_to_tree(&inserted)->left->left->value == 4);
    assert(!zipper_to_tree(&removed)->left->left && !root.left->left);
    zipper root_again = zipper_up(&inserted);
    zipper right = zipper_right(&root_again);
    assert(zipper_value(&right) == 4);
    /* A result remains valid after freeing the snapshots from which it arose. */
    zipper_free(&original);
    zipper_free(&left);
    zipper_free(&deep);
    zipper_free(&parent);
    assert(zipper_to_tree(&changed)->left->right->value == 30);
    assert(zipper_to_tree(&sibling)->left->right->value == 50);
    zipper_free(&changed);
    zipper_free(&sibling);
    zipper_free(&removed);
    zipper_free(&inserted);
    zipper_free(&root_again);
    zipper_free(&right);
    zipper_free(&missing_up);
    zipper_free(&missing_left);

    assert(zipper_to_tree(&clone)->left->right->value == 3);
    zipper_free(&clone);

    // The idiomatic C++ alternative has the same persistent contracts, with RAII.
    using persistent_zipper::Node;
    auto tree_value = Node::make(1, Node::make(2, {}, Node::make(3)), Node::make(4));
    persistent_zipper::Zipper cpp_original(tree_value);
    auto cpp_deep = cpp_original.left()->right().value();
    auto cpp_changed = cpp_deep.set_value(30);
    auto cpp_branch = cpp_deep.set_value(50);
    assert(cpp_original.value() == 1 && cpp_deep.value() == 3);
    assert(tree_value->left->right->value == 3);
    assert(cpp_changed.to_tree()->left->right->value == 30);
    assert(cpp_branch.to_tree()->left->right->value == 50);
    assert(!cpp_original.up() && !cpp_original.left()->left());
    auto cpp_removed = cpp_changed.up()->set_right({});
    assert(!cpp_removed.right() && cpp_changed.value() == 30);
    auto cpp_inserted = cpp_removed.set_left(Node::make(7));
    assert(cpp_inserted.left()->value() == 7 && !cpp_removed.left());

    return 0;
}
